#!/usr/bin/env node
// SPDX-License-Identifier: Apache-2.0
// TCRN-CROSS-STORY-486 R2, AC2 (MIN-227 D28; TCRN-CROSS-SUB-348): the helper repository's documents
// are generated by the engine release and never edited by hand there; the generator lives here, in
// the engine repository. Into a helper working tree it writes:
//   - README.md, README.en.md, README.ja.md, README.ko.md and README.fr.md: the finalized helper
//     READMEs kept under docs/readme/<skill id>/ as templates, with the release version filled
//     into their {{version}} slots and nothing else changed;
//   - skill/<skill id>/: the skill directory exactly as skill-render writes it for that version;
//   - package.json: the helper's name, the engine's version, and the skill's description A.
// Then it lists every file of the working tree that the generated tree does not hold, for the
// release to remove with git rm. It deletes nothing: the files it generates are written over, and
// every other file is left as it was. Build first: skill-render runs from dist/build.
//
// Usage: node scripts/render-helper-docs.mjs --out <helper working tree> [--version <version>]
//   --out      an existing directory, the helper repository's working tree
//   --version  the version to generate for; package.json's version when omitted

import { realpathSync } from "node:fs";
import { lstat, mkdir, mkdtemp, readdir, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { runCli } from "../dist/build/packages/cli/src/index.js";
import { BRAND } from "../dist/build/packages/core/src/names.js";
import { NODE_FLOOR } from "../dist/build/packages/core/src/node-floor.js";
import { SKILL_DESCRIPTION } from "../dist/build/packages/core/src/skill-render.js";
import { README_NAMES, renderReadme } from "./render-readme.mjs";

export const REPOSITORY_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
// The finalized helper READMEs, one per language, each with the {{version}} slot.
export const HELPER_README_TEMPLATE_DIRECTORY = `docs/readme/${BRAND.helper.id}`;
// Where the skill directory sits in the helper repository.
export const HELPER_SKILL_DIRECTORY = `skill/${BRAND.helper.id}`;
// Files a helper working tree keeps that are not documents: never generated and never listed.
export const HELPER_KEPT_FILES = Object.freeze(["LICENSE", ".gitignore"]);
// Git's own entry (a directory, or a file in a linked worktree) and installed packages are not
// files of the working tree.
const SKIPPED_ENTRIES = new Set([".git", "node_modules"]);
const VERSION_SHAPE = /^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?$/u;

class RenderHelperDocsError extends Error {
  constructor(reasonCode, detail = null) {
    super(reasonCode);
    this.reasonCode = reasonCode;
    this.detail = detail;
  }
}

function parseArguments(argv) {
  const options = { out: null, version: null };
  for (let index = 0; index < argv.length; index += 2) {
    const flag = argv[index];
    const value = argv[index + 1];
    if (flag !== "--out" && flag !== "--version") throw new RenderHelperDocsError("HELPER_DOCS_ARGUMENT_UNKNOWN", flag);
    if (value === undefined || value.startsWith("--")) throw new RenderHelperDocsError("HELPER_DOCS_ARGUMENT_VALUE_MISSING", flag);
    if (options[flag.slice(2)] !== null) throw new RenderHelperDocsError("HELPER_DOCS_ARGUMENT_DUPLICATE", flag);
    options[flag.slice(2)] = value;
  }
  return options;
}

// The helper's package.json: its name, the version it is released at, the skill's description A,
// and the fields the helper has always carried; the Node.js floor is the engine's.
export function helperPackageJson(version) {
  const manifest = {
    name: BRAND.helper.id,
    version,
    private: true,
    description: SKILL_DESCRIPTION,
    license: "Apache-2.0",
    engines: { node: `>=${NODE_FLOOR}` },
  };
  return `${JSON.stringify(manifest, null, 2)}\n`;
}

// Every file under root, relative to it with POSIX separators, in code-point order.
async function listFiles(root, prefix = "") {
  const found = [];
  const directory = prefix === "" ? root : join(root, ...prefix.split("/"));
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    if (SKIPPED_ENTRIES.has(entry.name)) continue;
    const path = prefix === "" ? entry.name : `${prefix}/${entry.name}`;
    if (entry.isDirectory()) found.push(...await listFiles(root, path));
    else found.push(path);
  }
  return found.sort();
}

async function readTemplate(root, name) {
  try {
    return await readFile(join(root, ...HELPER_README_TEMPLATE_DIRECTORY.split("/"), name), "utf8");
  } catch (error) {
    if (error?.code === "ENOENT") throw new RenderHelperDocsError("HELPER_DOCS_TEMPLATE_MISSING", `${HELPER_README_TEMPLATE_DIRECTORY}/${name}`);
    throw error;
  }
}

// The skill directory as skill-render writes it for the version, rendered into a directory of its
// own and read back file by file.
async function renderSkill(version) {
  const scratch = await mkdtemp(join(tmpdir(), "einzbern-helper-skill-"));
  try {
    const out = join(scratch, "skill");
    let output = "";
    try {
      await runCli(["skill-render", "--out", out, "--version", version], { write: (value) => { output += value; } });
    } catch (error) {
      throw new RenderHelperDocsError(typeof error?.reasonCode === "string" ? error.reasonCode : "HELPER_DOCS_SKILL_RENDER_FAILED", String(error?.message ?? error));
    }
    const report = JSON.parse(output);
    const files = new Map();
    for (const path of report.files) files.set(path, await readFile(join(out, ...path.split("/"))));
    return { files, installTreeDigest: report.installTreeDigest };
  } finally {
    await rm(scratch, { recursive: true, force: true });
  }
}

async function writeGenerated(out, path, bytes) {
  const target = join(out, ...path.split("/"));
  await mkdir(dirname(target), { recursive: true });
  await writeFile(target, bytes);
}

/**
 * Generate the helper repository's documents into `out` for `version` (package.json's version by
 * default) and list the files of `out` the generated tree does not hold. Everything is rendered
 * before the first file is written.
 */
export async function renderHelperDocs({ out, version = null, root = REPOSITORY_ROOT }) {
  if (typeof out !== "string" || out.length === 0) throw new RenderHelperDocsError("HELPER_DOCS_OUT_REQUIRED");
  const target = resolve(out);
  const stats = await lstat(target).catch(() => null);
  if (stats === null || !stats.isDirectory()) throw new RenderHelperDocsError("HELPER_DOCS_OUT_NOT_DIRECTORY", target);
  const resolved = version ?? JSON.parse(await readFile(join(root, "package.json"), "utf8")).version;
  if (typeof resolved !== "string" || !VERSION_SHAPE.test(resolved)) throw new RenderHelperDocsError("HELPER_DOCS_VERSION_INVALID", String(resolved));

  const generated = new Map();
  for (const name of README_NAMES) generated.set(name, Buffer.from(renderReadme(await readTemplate(root, name), resolved), "utf8"));
  const skill = await renderSkill(resolved);
  for (const [path, bytes] of skill.files) generated.set(`${HELPER_SKILL_DIRECTORY}/${path}`, bytes);
  generated.set("package.json", Buffer.from(helperPackageJson(resolved), "utf8"));

  for (const [path, bytes] of generated) await writeGenerated(target, path, bytes);
  const extraFiles = (await listFiles(target)).filter((path) => !generated.has(path) && !HELPER_KEPT_FILES.includes(path));
  return {
    ok: true,
    reasonCode: "HELPER_DOCS_RENDERED",
    version: resolved,
    out: target,
    files: [...generated.keys()].sort(),
    skillInstallTreeDigest: skill.installTreeDigest,
    extraFiles,
  };
}

// Node resolves the entry module to its real path while argv keeps the path as typed, so both are
// compared as real paths (the macOS temporary directory is a symlink).
function invokedDirectly() {
  if (!process.argv[1]) return false;
  try {
    return realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url));
  } catch {
    return false;
  }
}

if (invokedDirectly()) {
  try {
    const options = parseArguments(process.argv.slice(2));
    const result = await renderHelperDocs(options);
    process.stdout.write(`${JSON.stringify(result)}\n`);
  } catch (error) {
    const reasonCode = typeof error?.reasonCode === "string" ? error.reasonCode : String(error?.message ?? error);
    const detail = error instanceof RenderHelperDocsError ? error.detail : String(error?.message ?? error);
    process.stdout.write(`${JSON.stringify({ ok: false, reasonCode, detail })}\n`);
    process.exitCode = 1;
  }
}
